<a class="nav-link" href="verificar-correo.php">Verificar correo</a><a class="nav-link" href="gestion.php">Gestión</a></div></div></nav><main class="container py-4"><h1 class="titulo-seccion">Crear cuenta</h1><section class="tn-panel"><p>Regístrate con información <strong>ficticia</strong> para las pruebas. Auth y Clients deben confirmar ambos registros.</p><form id="registroForm" class="row g-3"><div class="col-md-6"><label for="reg-username" class="form-label">Usuario (minúsculas)</label><input id="reg-username" name="username" class="form-control" pattern="[a-z][a-z0-9_]{2,31}" required autocomplete="username"></div><div class="col-md-6"><label for="reg-password" class="form-label">Contraseña (mín. 8 caracteres)</label><input id="reg-password" type="password" name="password" class="form-control" minlength="8" required autocomplete="new-password"></div><div class="col-md-6"><label for="reg-run" class="form-label">RUN ficticio</label><input id="reg-run" name="run" class="form-control" minlength="7" required></div><div class="col-md-6"><label for="reg-nombre" class="form-label">Nombre completo</label><input id="reg-nombre" name="nombre" class="form-control" minlength="3" required></div><div class="col-md-6"><label for="reg-correo" class="form-label">Correo ficticio o de prueba</label><input id="reg-correo" name="correo" type="email" class="form-control" required></div><div class="col-md-6"><label for="reg-telefono" class="form-label">Teléfono</label><input id="reg-telefono" name="telefono" minlength="8" class="form-control" required></div><div class="col-md-6"><label for="reg-direccion" class="form-label">Dirección</label><input id="reg-direccion" name="direccion" class="form-control" minlength="5" required></div><div class="col-md-6"><label for="reg-comuna" class="form-label">Comuna</label><input id="reg-comuna" name="comuna" class="form-control" required></div><div class="col-md-6"><label for="reg-provincia" class="form-label">Provincia</label><input id="reg-provincia" name="provincia" class="form-control" required></div><div class="col-md-6"><label for="reg-region" class="form-label">Región</label><input id="reg-region" name="region" class="form-control" required></div><div class="col-md-6"><label for="reg-fecha" class="form-label">Fecha de nacimiento</label><input id="reg-fecha" name="fecha_nacimiento" type="date" class="form-control" required></div><div class="col-md-6"><label for="reg-sexo" class="form-label">Sexo</label><select id="reg-sexo" name="sexo" class="form-select" required><option value="">Seleccionar</option><option value="F">F</option><option value="M">M</option><option value="X">Prefiero no especificar</option></select></div><div class="col-12"><button class="tn-btn" type="submit">Registrar usuario y perfil</button> <a href="login.php">Ya tengo cuenta</a></div></form><div id="registroStatus" class="tn-status alert mt-3" aria-live="polite"></div></section></main></body></html>